arguments.content:
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 20px;
    background-color: #f4f4f4;
}

#main-container {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    gap: 20px;
    max-width: 1400px;
    margin: 0 auto;
}

#visualization {
    flex: 2;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

#details {
    flex: 1;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
    max-height: 90vh;
    overflow-y: auto;
}

#bubble-chart {
    width: 100%;
    height: 700px;
    position: relative;
}

circle {
    cursor: pointer;
    transition: all 0.2s;
}

circle:hover {
    stroke: #000;
    stroke-width: 2px;
}

circle.highlighted {
    stroke: #000;
    stroke-width: 3px;
    fill-opacity: 1;
}

circle.dimmed {
    fill-opacity: 0.3;
}

text.bubble-label {
    pointer-events: none;
    font-size: 10px;
    fill: #333;
    text-anchor: middle;
}

#table-container {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    padding: 10px;
    text-align: left;
    border-bottom: 1px solid #ddd;
}

th {
    background-color: #f8f8f8;
    position: sticky;
    top: 0;
}

tr:hover {
    background-color: #f1f1f1;
    cursor: pointer;
}

tr.selected {
    background-color: #e0e0e0;
    font-weight: bold;
}

.tooltip {
    position: absolute;
    text-align: center;
    padding: 8px;
    font: 12px sans-serif;
    background: rgba(0, 0, 0, 0.8);
    color: white;
    border-radius: 4px;
    pointer-events: none;
    z-index: 100;
}

#legends {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 10px;
}

.legend-item {
    display: flex;
    align-items: center;
    font-size: 12px;
}

.legend-color {
    width: 12px;
    height: 12px;
    margin-right: 5px;
    border-radius: 2px;
}

async function init() {
    const data = await d3.csv("data/stock-descriptions.csv");

    // Process data
    data.forEach(d => {
        d.marketCapVal = d.marketCap ? parseFloat(d.marketCap) : 0;
        // Identify ETFs: User said "ETF entries have no marketCap, country, or website data"
        // Also the prompt says "ETFs don't have market cap data, so size them uniformly"
        // We can check if marketCap is empty or N/A. In the CSV it might be empty string.
        d.isETF = !d.marketCap || d.marketCap === "" || isNaN(d.marketCapVal);
        if (d.isETF) {
            d.marketCapVal = 100000000000; // Arbitrary size for visualization (e.g. 100B equivalent)
        }
    });

    const width = document.getElementById('bubble-chart').clientWidth;
    const height = 700;
    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    // Sectors
    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    // Size Scale
    const minCap = d3.min(data.filter(d => !d.isETF), d => d.marketCapVal);
    const maxCap = d3.max(data, d => d.marketCapVal);
    const sizeScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([15, 60]); // Adjust range as needed

    // Clusters layout: Arrange sector centers in a circle or grid
    // For simplicity, let's use a circle of centers
    const centers = {};
    const radius = Math.min(width, height) * 0.35;
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI;
        centers[sector] = {
            x: width / 2 + radius * Math.cos(angle),
            y: height / 2 + radius * Math.sin(angle)
        };
    });

    // Force Simulation
    const simulation = d3.forceSimulation(data)
        .force("charge", d3.forceManyBody().strength(-5))
        .force("x", d3.forceX(d => centers[d.sector] ? centers[d.sector].x : width / 2).strength(0.1))
        .force("y", d3.forceY(d => centers[d.sector] ? centers[d.sector].y : height / 2).strength(0.1))
        .force("collide", d3.forceCollide(d => (d.isETF ? 20 : sizeScale(d.marketCapVal)) + 2).strength(0.9));

    // Tooltip
    const tooltip = d3.select("#tooltip");

    // Draw Bubbles
    const nodes = svg.selectAll("g")
        .data(data)
        .enter()
        .append("g")
        .attr("class", "node");

    const circles = nodes.append("circle")
        .attr("r", d => d.isETF ? 20 : sizeScale(d.marketCapVal))
        .attr("fill", d => colorScale(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5)
        .on("mouseover", function(event, d) {
            if (d.isETF) return;
            tooltip.transition().duration(200).style("opacity", .9);
            tooltip.html(`<strong>${d.ticker}</strong><br/>${d["full name"]}<br/>${d.sector}`)
                .style("left", (event.pageX) + "px")
                .style("top", (event.pageY - 28) + "px");
        })
        .on("mouseout", function(d) {
            tooltip.transition().duration(500).style("opacity", 0);
        })
        .on("click", function(event, d) {
            highlightStock(d.ticker);
        });

    const labels = nodes.append("text")
        .attr("class", "bubble-label")
        .attr("dy", ".3em")
        .text(d => d.ticker);

    simulation.on("tick", () => {
        nodes.attr("transform", d => `translate(${d.x},${d.y})`);
    });

    // Legends
    const legendContainer = d3.select("#legends");
    sectors.forEach(sector => {
        const item = legendContainer.append("div").attr("class", "legend-item");
        item.append("div")
            .attr("class", "legend-color")
            .style("background-color", colorScale(sector));
        item.append("span").text(sector);
    });

    // Table
    const tableBody = d3.select("#stock-table tbody");

    function formatMarketCap(val) {
        if (!val) return "N/A";
        val = parseFloat(val);
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val.toLocaleString();
    }

    const rows = tableBody.selectAll("tr")
        .data(data)
        .enter()
        .append("tr")
        .on("click", (event, d) => highlightStock(d.ticker));

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d["full name"]);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => d.isETF ? "N/A" : formatMarketCap(d.marketCap));

    // Interaction Logic
    function highlightStock(ticker) {
        // Reset
        circles.classed("highlighted", false).classed("dimmed", true);
        rows.classed("selected", false);

        // Highlight
        circles.filter(d => d.ticker === ticker)
            .classed("highlighted", true)
            .classed("dimmed", false);

        const selectedRow = rows.filter(d => d.ticker === ticker)
            .classed("selected", true);

        // Scroll row into view
        selectedRow.node().scrollIntoView({ behavior: "smooth", block: "center" });
    }

    // Clear highlight when clicking on background
    svg.on("click", function(event) {
        if (event.target.tagName === "svg") {
            circles.classed("highlighted", false).classed("dimmed", false);
            rows.classed("selected", false);
        }
    });
}

init();
